// Pixel-exact check of the screens against the design.py mock() renders (golden_*.rle,
// generated by `design.py golden`), plus weather helpers.
#include <math.h>
#include <stdio.h>
#include <string.h>
#include <unity.h>

#include <vector>

#include "screens.h"
#include "weather.h"

using namespace oralb;

struct BufCanvas : Canvas {
  std::vector<uint32_t> px;
  BufCanvas() : px(320 * 240, 0xFF00FF) {}
  void fill_rect(int x, int y, int w, int h, uint32_t rgb) override {
    for (int j = y; j < y + h; j++)
      for (int i = x; i < x + w; i++)
        if (i >= 0 && j >= 0 && i < width && j < height) px[j * width + i] = rgb;
  }
};

static std::vector<uint32_t> load_golden(const char* name) {
  char path[128];
  snprintf(path, sizeof path, TEST_DATA_DIR "/golden_%s.rle", name);
  FILE* f = fopen(path, "rb");
  TEST_ASSERT_NOT_NULL_MESSAGE(f, path);
  std::vector<uint32_t> out;
  unsigned char b[5];
  while (fread(b, 1, 5, f) == 5) {
    int run = b[0] | (b[1] << 8);
    uint32_t rgb = (b[2] << 16) | (b[3] << 8) | b[4];
    out.insert(out.end(), run, rgb);
  }
  fclose(f);
  TEST_ASSERT_EQUAL_UINT(320 * 240, out.size());
  return out;
}

// design.py demo_coverage(): zones fill one after another along this path
static void demo_cov(Scene& s, double progress) {
  static const char* order[16] = {"UOL", "UOF", "UOR", "UIR", "UIF", "UIL", "UCL", "UCR",
                                  "LOR", "LOF", "LOL", "LIL", "LIF", "LIR", "LCR", "LCL"};
  double n = progress * 16;
  for (int i = 0; i < 16; i++) {
    double frac = fmax(0.0, fmin(1.0, n - i));
    s.cov[zone_index(order[i])] = frac >= 1.0 ? 2 : (frac > 0 ? 1 : 0);
  }
}

static void expect_match(const char* name, const Scene& s) {
  BufCanvas c;
  draw_scene(c, s);
  std::vector<uint32_t> g = load_golden(name);
  int diff = 0, first = -1;
  for (size_t i = 0; i < g.size(); i++)
    if (g[i] != c.px[i]) {
      if (first < 0) first = (int)i;
      diff++;
    }
  char msg[96];
  snprintf(msg, sizeof msg, "%s: %d differing pixels, first at (%d,%d)", name, diff, first % 320, first / 320);
  TEST_ASSERT_EQUAL_INT_MESSAGE(0, diff, msg);
}

static void test_clock() {
  Scene s;
  s.screen = Screen::CLOCK;
  s.time_valid = true;
  s.hh = 7; s.mm = 42; s.weekday = 5; s.day = 10; s.month = 10;
  s.weather_valid = true; s.weather = Icon::PARTLY; s.temp = 12;
  s.alert = AlertLevel::NONE;
  expect_match("clock", s);
}

static void test_clock_colon_blink() {
  Scene s;
  s.screen = Screen::CLOCK;
  s.time_valid = true;
  s.colon = false;  // odd second
  s.hh = 7; s.mm = 42; s.weekday = 5; s.day = 10; s.month = 10;
  s.weather_valid = true; s.weather = Icon::PARTLY; s.temp = 12;
  s.alert = AlertLevel::NONE;
  expect_match("clock_colon_off", s);
}

static void test_brushing() {
  Scene s;
  s.screen = Screen::BRUSHING; s.secs = 83; s.zones = true; s.blink_on = true;
  demo_cov(s, 0.38);
  s.current_zone = zone_index("UIL");
  expect_match("brushing", s);
}

static void test_pressure() {
  Scene s;
  s.screen = Screen::BRUSHING; s.secs = 47; s.zones = true; s.blink_on = true; s.high_pressure = true;
  demo_cov(s, 0.2);
  s.current_zone = zone_index("UOR");
  expect_match("pressure", s);
}

static void test_result_good() {
  Scene s;
  s.screen = Screen::RESULT; s.secs = 134; s.zones = true;
  demo_cov(s, 1.0);
  expect_match("result_good", s);
}

static void test_result_short() {
  Scene s;
  s.screen = Screen::RESULT; s.secs = 52; s.zones = true;
  demo_cov(s, 0.4);
  expect_match("result_short", s);
}

static void test_no_zones_layouts_draw_inside_screen() {
  // not in the mockups: just make sure the centred variants render something and keep the
  // timer block vertically centred (rows 81..169 used, nothing below the progress row).
  Scene s;
  s.screen = Screen::BRUSHING; s.secs = 83; s.zones = false;
  BufCanvas c;
  draw_scene(c, s);
  int top = -1, bottom = -1;
  for (int y = 0; y < 240; y++)
    for (int x = 0; x < 320; x++)
      if (c.px[y * 320 + x] != 0) { if (top < 0) top = y; bottom = y; }
  TEST_ASSERT_EQUAL_INT(81, top);
  TEST_ASSERT_EQUAL_INT(158, bottom);  // progress row: 76 + 71 + 12 - 1
}

static void test_utf8_and_text_width() {
  TEST_ASSERT_EQUAL_INT(7 * 8 * 2, text_width("\xD0\xA7\xD1\x83\xD0\xB4\xD0\xBE\xD0\xB2\xD0\xBE!", 2));  // Чудово!
  const char* p = "\xD0\x9B""a";
  TEST_ASSERT_EQUAL_INT(0x041B, utf8_decode(p));
  TEST_ASSERT_EQUAL_INT('a', utf8_decode(p));
  const char* q = "\xC2\xB0";
  TEST_ASSERT_EQUAL_INT(0xB0, utf8_decode(q));
}

static void test_wmo_mapping() {
  TEST_ASSERT_TRUE(icon_from_wmo(0) == Icon::CLEAR);
  TEST_ASSERT_TRUE(icon_from_wmo(1) == Icon::CLEAR);
  TEST_ASSERT_TRUE(icon_from_wmo(2) == Icon::PARTLY);
  TEST_ASSERT_TRUE(icon_from_wmo(3) == Icon::CLOUDY);
  TEST_ASSERT_TRUE(icon_from_wmo(45) == Icon::FOG);
  TEST_ASSERT_TRUE(icon_from_wmo(48) == Icon::FOG);
  TEST_ASSERT_TRUE(icon_from_wmo(51) == Icon::RAIN);
  TEST_ASSERT_TRUE(icon_from_wmo(67) == Icon::RAIN);
  TEST_ASSERT_TRUE(icon_from_wmo(81) == Icon::RAIN);
  TEST_ASSERT_TRUE(icon_from_wmo(71) == Icon::SNOW);
  TEST_ASSERT_TRUE(icon_from_wmo(77) == Icon::SNOW);
  TEST_ASSERT_TRUE(icon_from_wmo(86) == Icon::SNOW);
  TEST_ASSERT_TRUE(icon_from_wmo(95) == Icon::STORM);
  TEST_ASSERT_TRUE(icon_from_wmo(99) == Icon::STORM);
}

static void clock_scene(Scene& s, int hh, int mm, Icon icon, int temp, AlertLevel a, const char* since) {
  s.screen = Screen::CLOCK;
  s.time_valid = true;
  s.hh = hh; s.mm = mm; s.weekday = 5; s.day = 10; s.month = 10;
  s.weather_valid = true; s.weather = icon; s.temp = temp;
  s.alert = a;
  strcpy(s.alert_since, since);
}

static void test_clock_alerts() {
  Scene y;
  clock_scene(y, 20, 47, Icon::PARTLY_NIGHT, 13, AlertLevel::YELLOW, "20:30");
  expect_match("clock_alert_yellow", y);
  Scene r;
  clock_scene(r, 20, 52, Icon::PARTLY_NIGHT, 13, AlertLevel::RED, "20:49");
  expect_match("clock_alert_red", r);
  Scene u;
  clock_scene(u, 7, 42, Icon::PARTLY, 12, AlertLevel::UNKNOWN, "");  // unknown: block hidden
  expect_match("clock_alert_unknown", u);
}

static void test_clock_night_icons() {
  Scene s;
  s.screen = Screen::CLOCK;
  s.time_valid = true;
  s.hh = 23; s.mm = 15; s.weekday = 5; s.day = 10; s.month = 10;
  s.weather_valid = true; s.weather = Icon::CLEAR_NIGHT; s.temp = 9;
  s.alert = AlertLevel::NONE;
  expect_match("clock_night", s);

  Scene p;
  p.screen = Screen::CLOCK;
  p.time_valid = true;
  p.hh = 2; p.mm = 40; p.weekday = 5; p.day = 10; p.month = 10;
  p.weather_valid = true; p.weather = Icon::PARTLY_NIGHT; p.temp = 7;
  p.alert = AlertLevel::NONE;
  expect_match("clock_night_partly", p);
}

// Captured-style Open-Meteo reply (current + daily, timezone=auto)
static const char* REPLY =
    "{\"latitude\":50.45,\"longitude\":30.52,\"generationtime_ms\":0.1,\"utc_offset_seconds\":10800,"
    "\"timezone\":\"Europe/Kyiv\",\"timezone_abbreviation\":\"GMT+3\",\"elevation\":169.0,"
    "\"current_units\":{\"time\":\"iso8601\",\"interval\":\"seconds\",\"temperature_2m\":\"\xC2\xB0""C\","
    "\"weather_code\":\"wmo code\",\"is_day\":\"\"},"
    "\"current\":{\"time\":\"2026-10-10T18:00\",\"interval\":900,\"temperature_2m\":-3.6,\"weather_code\":2,\"is_day\":1},"
    "\"daily_units\":{\"time\":\"iso8601\",\"sunrise\":\"iso8601\",\"sunset\":\"iso8601\"},"
    "\"daily\":{\"time\":[\"2026-10-10\"],\"sunrise\":[\"2026-10-10T06:58\"],\"sunset\":[\"2026-10-10T18:12\"]}}";

static void test_open_meteo_parse() {
  WeatherData w;
  TEST_ASSERT_TRUE(parse_open_meteo(REPLY, w));
  TEST_ASSERT_EQUAL_INT(2, w.code);
  TEST_ASSERT_TRUE(fabsf(w.temp_c + 3.6f) < 1e-4f);
  TEST_ASSERT_TRUE(w.has_is_day && w.is_day);
  TEST_ASSERT_TRUE(w.has_sun);
  TEST_ASSERT_EQUAL_INT(6 * 60 + 58, w.sunrise_min);
  TEST_ASSERT_EQUAL_INT(18 * 60 + 12, w.sunset_min);

  // current only (no daily, no is_day): still parses, no sun / is_day info
  WeatherData c;
  TEST_ASSERT_TRUE(parse_open_meteo(
      "{\"current\":{\"time\":\"2026-10-10T15:00\",\"temperature_2m\":15.4,\"weather_code\":71}}", c));
  TEST_ASSERT_EQUAL_INT(71, c.code);
  TEST_ASSERT_FALSE(c.has_sun);
  TEST_ASSERT_FALSE(c.has_is_day);

  // is_day without daily
  WeatherData d;
  TEST_ASSERT_TRUE(parse_open_meteo("{\"current\":{\"temperature_2m\":1.0,\"weather_code\":0,\"is_day\":0}}", d));
  TEST_ASSERT_TRUE(d.has_is_day && !d.is_day && !d.has_sun);

  // malformed daily keeps the current data
  WeatherData m;
  TEST_ASSERT_TRUE(parse_open_meteo(
      "{\"current\":{\"temperature_2m\":1.0,\"weather_code\":0},\"daily\":{\"sunrise\":[],\"sunset\":[\"x\"]}}", m));
  TEST_ASSERT_FALSE(m.has_sun);

  WeatherData bad;
  TEST_ASSERT_FALSE(parse_open_meteo("{\"error\":true}", bad));
}

static void test_day_night_decision() {
  WeatherData w;
  TEST_ASSERT_TRUE(parse_open_meteo(REPLY, w));  // sunrise 06:58, sunset 18:12
  const int rise = 6 * 60 + 58, set = 18 * 60 + 12;
  TEST_ASSERT_FALSE(is_daytime(w, rise - 1, true));
  TEST_ASSERT_TRUE(is_daytime(w, rise, true));
  TEST_ASSERT_TRUE(is_daytime(w, set - 1, true));
  TEST_ASSERT_FALSE(is_daytime(w, set, true));  // at sunset = night
  TEST_ASSERT_FALSE(is_daytime(w, 0, true));
  // icon: code 2 (partly) swaps, cloudy does not
  TEST_ASSERT_TRUE(weather_icon(w, 12 * 60, true) == Icon::PARTLY);
  TEST_ASSERT_TRUE(weather_icon(w, set, true) == Icon::PARTLY_NIGHT);
  w.code = 0;
  TEST_ASSERT_TRUE(weather_icon(w, rise - 1, true) == Icon::CLEAR_NIGHT);
  TEST_ASSERT_TRUE(weather_icon(w, rise, true) == Icon::CLEAR);
  w.code = 3;
  TEST_ASSERT_TRUE(weather_icon(w, 23 * 60, true) == Icon::CLOUDY);
  w.code = 61;
  TEST_ASSERT_TRUE(weather_icon(w, 23 * 60, true) == Icon::RAIN);

  // no sun times: is_day decides (clock valid or not)
  WeatherData n;
  n.code = 0; n.has_is_day = true; n.is_day = false;
  TEST_ASSERT_TRUE(weather_icon(n, 12 * 60, true) == Icon::CLEAR_NIGHT);
  TEST_ASSERT_TRUE(weather_icon(n, 0, false) == Icon::CLEAR_NIGHT);
  n.is_day = true;
  TEST_ASSERT_TRUE(weather_icon(n, 3 * 60, true) == Icon::CLEAR);

  // neither: 07:00-19:00 is day
  WeatherData f;
  f.code = 2;
  TEST_ASSERT_TRUE(weather_icon(f, 7 * 60 - 1, true) == Icon::PARTLY_NIGHT);
  TEST_ASSERT_TRUE(weather_icon(f, 7 * 60, true) == Icon::PARTLY);
  TEST_ASSERT_TRUE(weather_icon(f, 19 * 60 - 1, true) == Icon::PARTLY);
  TEST_ASSERT_TRUE(weather_icon(f, 19 * 60, true) == Icon::PARTLY_NIGHT);
  TEST_ASSERT_TRUE(weather_icon(f, 3 * 60, false) == Icon::PARTLY);  // no clock, no info: day
}

void run_screen_tests() {
  RUN_TEST(test_clock);
  RUN_TEST(test_clock_colon_blink);
  RUN_TEST(test_clock_night_icons);
  RUN_TEST(test_clock_alerts);
  RUN_TEST(test_brushing);
  RUN_TEST(test_pressure);
  RUN_TEST(test_result_good);
  RUN_TEST(test_result_short);
  RUN_TEST(test_no_zones_layouts_draw_inside_screen);
  RUN_TEST(test_utf8_and_text_width);
  RUN_TEST(test_wmo_mapping);
  RUN_TEST(test_open_meteo_parse);
  RUN_TEST(test_day_night_decision);
}
